  "<span>First assign a Design Field to at least one object in the design (right panel), then AI will fill them.</span></div></div>": "<span>まずデザイン内の少なくとも 1 つのオブジェクトにデザイン フィールドを割り当てます (右パネル)。次に AI がそれらを埋めます。</span></div></div>",
  "This request comes from the Bulk Builder (PLAN pass). Read the instruction and the design fields, then LIST the outputs you will produce, LABELS ONLY (no field content). Return ONLY a raw JSON object: {\"translate\": <true ONLY if the instruction asks to translate/localize into languages, else false>, \"labels\": [ ... ]}. When translate is true the labels are the LANGUAGE NAMES (written in the same language the user used). Otherwise the labels are a distinct short topic/seed per output. Honor any quantity named in the instruction; otherwise a sensible set (about 6 to 12). Hard cap 500.\n": "このリクエストは、Bulk Builder (PLAN パス) から送信されます。指示と設計フィールドを読み、作成する出力をラベルのみ (フィールド内容なし) でリストします。生の JSON オブジェクトのみを返します: {\"translate\": <true ONLY if the instruction asks to translate/localize into languages, else false>, \"labels\": [ ... ]}。 translation が true の場合、ラベルは言語名 (ユーザーが使用したのと同じ言語で書かれたもの) になります。それ以外の場合、ラベルは出力ごとに個別の短いトピック/シードになります。指示に指定されている数量を尊重します。それ以外の場合は、妥当なセット (約 6 ～ 12)。ハードキャップ500。\n",
