  "Create your dika studio account": "dika studio アカウントを作成",
  "An account unlocks the online template and asset library, and release news. The editor itself works either way.": "アカウントを作成すると、オンラインテンプレート、アセットライブラリ、リリース情報を利用できます。エディターはアカウントなしでも使えます。",
  "This app could not reach dika studio just now, so the full sign-up flow is not available.": "現在このアプリから dika studio に接続できないため、完全な登録フローは利用できません。",
  "You can carry on using the editor: everything except the online library works offline.": "エディターの使用を続行できます。オンライン ライブラリ以外はすべてオフラインで動作します。",
  "It will ask again next time you open it.": "次回開くときに再度尋ねられます。",
