  "<div style=\"font-size:13px;color:var(--text-dim);margin-bottom:20px\">Multi-Product Design Platform</div>": "<div style=\"font-size:13px;color:var(--text-dim);margin-bottom:20px\">複数商品デザインプラットフォーム</div>",
  "<div style=\"font-size:12px;color:var(--text-faint);margin-bottom:4px\">Version 2.0</div>": "<div style=\"font-size:12px;color:var(--text-faint);margin-bottom:4px\">バージョン 2.0</div>",
  "<div style=\"font-size:12px;color:var(--text-faint);margin-bottom:20px\">Built by <a href=\"https://mirexagency.com\" target=\"_blank\" rel=\"noopener\" style=\"color:var(--gold);text-decoration:none\">Mirex Agency</a></div>": "<div style=\"font-size:12px;color:var(--text-faint);margin-bottom:20px\">制作： <a href=\"https://mirexagency.com\" target=\"_blank\" rel=\"noopener\" style=\"color:var(--gold);text-decoration:none\">Mirex Agency</a></div>",
  "<div style=\"font-size:11px;color:var(--text-faint);margin-bottom:22px\">&copy; 2026 Mirex Agency. Released under the Business Source License 1.1.</div>": "<div style=\"font-size:11px;color:var(--text-faint);margin-bottom:22px\">© 2026 Mirex Agency. Business Source License 1.1.</div> でリリースされました。",
  "<div style=\"font-size:11px;color:var(--text-faint);margin-top:10px\">Reset clears only the wizard's own record. Your projects, settings and keys are untouched.</div>": "<div style=\"font-size:11px;color:var(--text-faint);margin-top:10px\">リセットで消去されるのはウィザードの記録だけです。プロジェクト、設定、キーは変更されません。</div>",
  "<p style=\"color:var(--text-dim);font-size:13px;margin-bottom:16px\">Need help? Contact us:</p>": "<p style=\"color:var(--text-dim);font-size:13px;margin-bottom:16px\">お困りですか？お問い合わせください：</p>",
  "<div style=\"margin-bottom:12px\"><a href=\"https://mirexagency.com\" target=\"_blank\" rel=\"noopener\" style=\"color:var(--gold);text-decoration:none;font-size:13px\">Visit our website</a></div>": "<div style=\"margin-bottom:12px\"><a href=\"https://mirexagency.com\" target=\"_blank\" rel=\"noopener\" style=\"color:var(--gold);text-decoration:none;font-size:13px\">ウェブサイトを見る</a></div>",
  "<div style=\"margin-bottom:12px\"><a href=\"mailto:support@dika.studio\" style=\"color:var(--gold);text-decoration:none;font-size:13px\">Email support@dika.studio</a></div>": "<div style=\"margin-bottom:12px\"><a href=\"mailto:support@dika.studio\" style=\"color:var(--gold);text-decoration:none;font-size:13px\">support@dika.studio にメールする</a></div>",
  "settings: about": "設定:概要",
