  "<button type=\"button\" class=\"btn-xs\" id=\"account-signout\" style=\"padding:7px 14px;background:transparent;border:1px solid var(--border);border-radius:4px;color:var(--text-dim);cursor:pointer;font-size:12px\">Sign out</button>": "<button type=\"button\" class=\"btn-xs\" id=\"account-signout\" style=\"padding:7px 14px;background:transparent;border:1px solid var(--border);border-radius:4px;color:var(--text-dim);cursor:pointer;font-size:12px\">ログアウト</button>",
