  "<span style=\"font-size:11px;color:var(--text-dim)\">AI subtitle models cache</span>": "<span style=\"font-size:11px;color:var(--text-dim)\">AI 字幕モデルのキャッシュ</span>",
  "<span id=\"set-model-cache-size\" style=\"font-size:12px;font-weight:600;color:var(--text)\">&hellip;</span>": "<span id=\"set-model-cache-size\" style=\"font-size:12px;font-weight:600;color:var(--text)\">…</span>",
  "<button id=\"set-clear-cache\" class=\"sbtn\" style=\"padding:8px 16px;width:auto;height:auto;font-size:12px;border-color:var(--red);color:var(--red)\">Clear All Cache</button>": "<button id=\"set-clear-cache\" class=\"sbtn\" style=\"padding:8px 16px;width:auto;height:auto;font-size:12px;border-color:var(--red);color:var(--red)\">すべてのキャッシュを消去</button>",
  "settings: preferences": "設定:環境設定",
