  "<div class=\"ps-stat\"><div class=\"ps-stat-num\" style=\"color:var(--gold)\">": "<div class=\"ps-stat\"><div class=\"ps-stat-num\" style=\"color:var(--gold)\">",
  "settings: sleep": "設定: スリープ",
  "<p style=\"color:var(--text-dim);font-size:13px;margin-bottom:12px\">Auto-save times from this browser. The latest state is stored under <span style=\"color:var(--text-faint);font-size:12px\">dika_autosave</span>; rolling snapshots use <span style=\"color:var(--text-faint);font-size:12px\">dika_versions</span>.</p>": "<p style=\"color:var(--text-dim);font-size:13px;margin-bottom:12px\">このブラウザからの時間を自動保存します。最新の状態は、<span style=\"color:var(--text-faint);font-size:12px\">dika_autosave</span> に保存されます。ローリング スナップショットは <span style=\"color:var(--text-faint);font-size:12px\">dika_versions</span>.</p> を使用します",
  "<div style=\"font-size:14px;color:var(--text)\">": "<div style=\"font-size:14px;color:var(--text)\">",
  "<p style=\"color:var(--text-dim);font-size:13px;margin:0\">No <code>dika_autosave</code> entry yet.</p>": "<p style=\"color:var(--text-dim);font-size:13px;margin:0\"><code>dika_autosave</code> のエントリはまだありません。</p>",
  "<ul id=\"settings-vh-list\" style=\"margin:0 0 12px 0;padding:0 0 0 18px;color:var(--text-dim);font-size:12px;max-height:240px;overflow-y:auto;line-height:1.4\">": "<ul id=\"settings-vh-list\" style=\"margin:0 0 12px 0;padding:0 0 0 18px;color:var(--text-dim);font-size:12px;max-height:240px;overflow-y:auto;line-height:1.4\">",
  " — <span style=\"color:var(--text-faint)\">": " — <span style=\"color:var(--text-faint)\">",
  "<p style=\"color:var(--text-faint);font-size:12px;margin-bottom:12px\">No rolling snapshots yet (they are added on each auto-save tick).</p>": "<p style=\"color:var(--text-faint);font-size:12px;margin-bottom:12px\">ローリングスナップショットはまだありません（自動保存ごとに追加されます）。</p>",
  "<span style=\"font-size:10px;color:var(--text-faint);margin-top:6px;display:block\">Clears stored version snapshots (<code>dika_versions</code>). Current canvas and latest auto-save file are not removed.</span>": "<span style=\"font-size:10px;color:var(--text-faint);margin-top:6px;display:block\">保存済みのバージョンスナップショットを消去します（<code>dika_versions</code>）。現在のキャンバスと最新の自動保存ファイルは削除されません。</span>",
