  "Search stock": "ストック素材を検索",
  "No folders yet. Click the button above to create one.": "まだフォルダがありません。上のボタンをクリックして作成します。",
  "No images uploaded yet.": "画像はまだアップロードされていません。",
  "Products, categories, brands and attributes come from the dika studio product catalogue.": "商品、カテゴリ、ブランド、属性は dika studio の商品カタログから取得されます。",
  "This is the offline Community Edition, so there is no catalogue to read from.": "これはオフラインのコミュニティ エディションであるため、読み取るためのカタログはありません。",
