  "Switch to Board Mode": "ボードモードに切り替える",
  "A new page will open as your whiteboard. You can draw, add shapes, sticky notes and connectors freely across the entire canvas.": "新しいページがホワイトボードとして開きます。キャンバス全体に自由に描画し、図形、付箋、コネクターを追加できます。",
  "Open Board": "ボードを開く",
